from content_helpers import code, output, choice, lesson, section, program

def sections():
    return [section("decisions", "4. Выбор и логика", "Программы принимают решения и обрабатывают границы.", [
        lesson("if", "Развилка if / else", "Выполните разные действия по условию.",
            "if (condition) { ... } выполняет блок, когда условие истинно. else { ... } задаёт альтернативу. Операторы >, <, >=, <=, ==, != сравнивают значения и возвращают bool. Равенство проверяют двумя знаками ==; один знак = присваивает.\n\nВсегда оформляйте ветви фигурными скобками: это облегчает добавление инструкций и защищает от путаницы. Не ставьте ; сразу после if (...): это создаст пустую инструкцию вместо ожидаемого блока. Если else не нужен, его можно опустить. В задачах внимательно решайте, к какой ветви относится равенство.",
            program('int energy = 0;\nstd::cin >> energy;\nif (energy >= 20) {\n    std::cout << "Ready";\n} else {\n    std::cout << "Charge";\n}'),
            "В условии допускается преобразование числового значения к bool: ноль означает false, ненулевое значение — true. Поэтому if (x = 5) может скомпилироваться и работать не так, как задумано. Используйте сравнение == и предупреждения компилятора; не запоминайте неверное правило «присваивание в if всегда синтаксическая ошибка».",
            "Отдельно проверьте значение ровно на границе. = записывает, == сравнивает.", [
                code("gate", "Шлюз по заряду", 'Ввод: целый заряд e от 0 до 100. Если e ≥ 20, выведите Ready, иначе Charge.', 'int e = 0;\nstd::cin >> e;\nif (e >= 20) {\n    std::cout << "Ready";\n} else {\n    std::cout << "Charge";\n}', [("19", "Charge"), ("20", "Ready"), ("100", "Ready")], ["Заряда ровно 20 уже достаточно.", "Используйте >=, а не >."], "Граничный тест 20 отличает правильное условие от слишком строгого."),
                output("equal", "Граница допуска", 'int height = 10;\nif (height > 10) {\n    std::cout << "High";\n} else {\n    std::cout << "Low";\n}', "Low", ["Строгое > не включает равенство.", "При height=10 условие ложно."], "Выбирается ветвь else."),
                code("max", "Больший отсек", 'Ввод: два целых объёма a,b (0…10000). Выведите больший. При равенстве выведите это общее значение.', 'int a = 0, b = 0;\nstd::cin >> a >> b;\nif (a > b) {\n    std::cout << a;\n} else {\n    std::cout << b;\n}', [("4 9", "9"), ("7 7", "7"), ("10 0", "10")], ["В каждой ветви выводится одна переменная.", "При равенстве можно выбрать любую из них."], "Контракт не просит имя отсека, только его объём."),
                choice("assign", "Ошибка без синтаксической ошибки", 'Почему if (x = 5) опасно, если вы хотели проверить равенство x и 5?', ["Оно присваивает 5 и затем проверяет ненулевое значение", "Оно всегда сравнивает правильно", "Такое условие никогда не компилируется"], 0, ["Один = — операция записи.", "Число 5 преобразуется в true."], "Намерение сравнить нужно записать как x == 5; предупреждение компилятора помогает, но не заменяет понимание."),
                code("difference", "Разница без минуса", 'Ввод: a,b от −100 до 100. Без std::abs выведите неотрицательную разницу между ними.', 'int a = 0, b = 0;\nstd::cin >> a >> b;\nif (a >= b) {\n    std::cout << a - b;\n} else {\n    std::cout << b - a;\n}', [("-3 5", "8"), ("7 7", "0"), ("10 -5", "15")], ["Вычитайте меньшее из большего.", "Условие a >= b определяет, какую разность выводить."], "Ветвление заменяет ещё не введённую библиотечную функцию.", difficulty=2)
            ], ["if", "else", "сравнения"]),
        lesson("logic", "Составные условия", "Соедините несколько требований без математических ловушек.",
            "&& означает логическое И: должны выполняться оба условия. || означает ИЛИ: достаточно хотя бы одного. ! меняет true на false и наоборот. Чтобы проверить включение x в отрезок [a,b], пишут a <= x && x <= b. Запись a <= x <= b не означает диапазон: это цепочка двух отдельных сравнений с промежуточным bool.\n\n&& и || вычисляются с коротким замыканием: правая часть && проверяется только при истинной левой, а правая часть || — только при ложной левой. Это позволяет написать divisor != 0 && value % divisor == 0 без деления на ноль. Скобки вокруг смысловых частей помогают читать логику; ! сильнее &&, а && сильнее ||.",
            program('int x = 0;\nstd::cin >> x;\nif (0 <= x && x <= 100) {\n    std::cout << "Inside";\n} else {\n    std::cout << "Outside";\n}'),
            "Короткое замыкание — гарантия встроенных логических операторов, используемых здесь с bool. Условие защиты должно стоять слева: сначала проверка делителя, потом операция. Перестановка частей может изменить безопасность выполнения.",
            "Составляйте отдельные сравнения и соединяйте &&/||. Не переносите математическую цепочку сравнений буквально.", [
                code("range", "Коридор температуры", 'Ввод: целая температура t от −100 до 100. Выведите Safe, если −10 ≤ t ≤ 40, иначе Alert.', 'int t = 0;\nstd::cin >> t;\nif (-10 <= t && t <= 40) {\n    std::cout << "Safe";\n} else {\n    std::cout << "Alert";\n}', [("-10", "Safe"), ("40", "Safe"), ("41", "Alert"), ("-11", "Alert")], ["Обе границы включены.", "Соедините два сравнения через &&."], "Требуется одновременно не быть ниже минимума и выше максимума."),
                output("short", "Защита от нуля", 'int divisor = 0;\nif (divisor != 0 && 12 % divisor == 0) {\n    std::cout << "Yes";\n} else {\n    std::cout << "No";\n}', "No", ["Левая часть && ложна.", "Остаток от деления вообще не вычисляется."], "Короткое замыкание делает этот конкретный код безопасным: выполняется else."),
                code("weekend", "День техобслуживания", 'Ввод: номер дня d от 1 до 7, где 6 и 7 — выходные. Выведите Maintenance для выходного, иначе Flight.', 'int d = 0;\nstd::cin >> d;\nif (d == 6 || d == 7) {\n    std::cout << "Maintenance";\n} else {\n    std::cout << "Flight";\n}', [("6", "Maintenance"), ("7", "Maintenance"), ("1", "Flight")], ["День не может одновременно равняться 6 и 7.", "Нужен || между d == 6 и d == 7."], "Логическое ИЛИ соответствует любому из двух допустимых значений."),
                choice("chain", "Диапазон не цепочка", 'Как правильно проверить 1 ≤ x ≤ 9 для int x?', ["1 <= x <= 9", "1 <= x && x <= 9", "x >= 1 || x <= 9"], 1, ["Нужно выполнение обеих границ.", "Повторите x в двух самостоятельных сравнениях."], "Цепочка сначала превращает первое сравнение в bool; ИЛИ пропускает значения вне диапазона."),
                code("clearance", "Допуск в лабораторию", 'Ввод: age (0…100) и badge (0 или 1). Допуск есть, если age ≥ 18 и badge=1, либо age ≥ 65 независимо от badge. Выведите Allow или Deny.', 'int age = 0, badge = 0;\nstd::cin >> age >> badge;\nif ((age >= 18 && badge == 1) || age >= 65) {\n    std::cout << "Allow";\n} else {\n    std::cout << "Deny";\n}', [("17 1", "Deny"), ("18 1", "Allow"), ("64 0", "Deny"), ("65 0", "Allow")], ["Есть два независимых способа получить допуск.", "Первый способ — пара условий с &&, второй присоединяется через ||."], "Скобки подчёркивают смысловую группу; проверяйте границы 18 и 65 отдельно.", difficulty=2)
            ], ["логика", "диапазоны", "короткое замыкание"]),
        lesson("branches", "Несколько вариантов", "Выберите ровно одно состояние.",
            "Цепочка if / else if / else проверяет условия сверху вниз и выполняет только первую подошедшую ветвь. В отличие от нескольких независимых if она исключает повторный вывод. Начинайте с условий, которые не будут случайно перекрыты более широкими.\n\nswitch (code) выбирает ветку case по целому значению или символу. break завершает switch; без него выполнение может перейти в следующий case. default обрабатывает остальные значения. Для диапазонов и сложной логики удобнее if, а для отдельных кодов — switch. В этом уроке break относится к switch; его роль в циклах изучим отдельно.",
            program('int code = 0;\nstd::cin >> code;\nswitch (code) {\ncase 1: std::cout << "Open"; break;\ncase 2: std::cout << "Close"; break;\ndefault: std::cout << "Unknown"; break;\n}'),
            "После выбора case стандарт не добавляет автоматический выход из switch. Иногда переход в следующий case намеренный, но в начальных задачах явно используем break. Для цепочки else if повторная проверка нижних ветвей после успешной верхней не происходит.",
            "Для ровно одного ответа используйте взаимоисключающую структуру, а не набор независимых выводов.", [
                code("sign", "Знак высоты", 'Ввод: целая высота h от −100 до 100. Выведите Below при h<0, Surface при h=0, Above при h>0.', 'int h = 0;\nstd::cin >> h;\nif (h < 0) {\n    std::cout << "Below";\n} else if (h == 0) {\n    std::cout << "Surface";\n} else {\n    std::cout << "Above";\n}', [("-1", "Below"), ("0", "Surface"), ("1", "Above")], ["Нужны три непересекающихся случая.", "После h<0 проверьте h==0; всё оставшееся положительно."], "Цепочка гарантирует ровно один вывод."),
                output("first", "Первая подходящая ветвь", 'int score = 90;\nif (score >= 60) {\n    std::cout << "Pass";\n} else if (score >= 90) {\n    std::cout << "Excellent";\n}', "Pass", ["Проверки идут сверху вниз.", "После первой истинной ветви else if пропускается."], "Если хотели Excellent для 90+, проверку высокого порога нужно поставить раньше."),
                code("switch", "Пульт шлюза", 'Ввод: целое c от 0 до 9. Используя switch, выведите Open для 1, Close для 2, Stop для 3 и Unknown для остальных.', 'int c = 0;\nstd::cin >> c;\nswitch (c) {\ncase 1: std::cout << "Open"; break;\ncase 2: std::cout << "Close"; break;\ncase 3: std::cout << "Stop"; break;\ndefault: std::cout << "Unknown"; break;\n}', [("1", "Open"), ("2", "Close"), ("3", "Stop"), ("9", "Unknown")], ["Каждому коду соответствует case.", "Завершите ветви break и добавьте default."], "Без break после case 1 могли бы напечататься и следующие состояния."),
                choice("fallthrough", "Почему два сообщения?", 'В switch после case 1 нет break, за ним идёт case 2 с выводом. Что возможно при выборе case 1?', ["Автоматический выход после первой инструкции", "Выполнение дойдёт до инструкций case 2", "Второй case никогда не компилируется"], 1, ["Метка case — точка входа, не автоматическая граница блока.", "Выход здесь задаёт break."], "Такой переход называется fallthrough; в этом курсе начальные решения делают его явным или исключают."),
                code("rating", "Оценка посадки", 'Ввод: score от 0 до 100. Выведите Excellent для 90…100, Good для 70…89, Pass для 50…69, Retry для 0…49.', 'int score = 0;\nstd::cin >> score;\nif (score >= 90) {\n    std::cout << "Excellent";\n} else if (score >= 70) {\n    std::cout << "Good";\n} else if (score >= 50) {\n    std::cout << "Pass";\n} else {\n    std::cout << "Retry";\n}', [("90", "Excellent"), ("89", "Good"), ("70", "Good"), ("50", "Pass"), ("49", "Retry")], ["Проверяйте пороги от большего к меньшему.", "Нижней ветви не нужно повторять верхнюю границу: она уже исключена."], "Порядок условий — часть алгоритма, а не просто оформление.", difficulty=2)
            ], ["else if", "switch", "границы"]),
        lesson("dispatcher", "Контрольная: диспетчер шлюза", "Соберите решения с несколькими правилами и проверьте приоритеты.",
            "Когда требований несколько, выпишите их приоритет. Например, авария должна перекрывать обычное разрешение на полёт. Сначала проверяют запреты высокого приоритета, затем обычные режимы. Для геометрических задач помните, что касание границы часто считается допустимым: это нужно прямо указать в условии.\n\nВ контрольной не используются циклы, функции или строки-переменные: только уже изученные числа, bool, ввод, арифметика и ветвления. Пробуйте крайние значения, равенство и конфликт правил. Не добавляйте неоговорённых ограничений.",
            program('int emergency = 0, energy = 0;\nstd::cin >> emergency >> energy;\nif (emergency == 1) {\n    std::cout << "Stop";\n} else if (energy >= 20) {\n    std::cout << "Go";\n} else {\n    std::cout << "Charge";\n}'),
            "Таблица решений помогает найти конфликт правил: при emergency=1 и energy=100 возможен только Stop. Тестирование не обязано перебирать все числа, но должно покрыть каждую ветвь и смысловые границы. Это не доказательство для произвольного кода, а практическая проверка конкретного алгоритма.",
            "Проверяйте приоритет запретов, границы диапазонов и ровно один итоговый ответ.", [
                code("emergency", "Приоритет аварии", 'Ввод: emergency (0 или 1), energy (0…100). При аварии выведите Stop независимо от заряда; иначе Go при energy≥20, иначе Charge.', 'int emergency = 0, energy = 0;\nstd::cin >> emergency >> energy;\nif (emergency == 1) {\n    std::cout << "Stop";\n} else if (energy >= 20) {\n    std::cout << "Go";\n} else {\n    std::cout << "Charge";\n}', [("1 100", "Stop"), ("0 20", "Go"), ("0 19", "Charge"), ("1 0", "Stop")], ["Первая проверка должна перекрывать все обычные режимы.", "Поставьте emergency == 1 перед проверкой заряда."], "Приоритет требований выражается порядком взаимоисключающих ветвей.", difficulty=2),
                output("twoifs", "Два независимых решения", 'int x = 5;\nif (x > 0) { std::cout << "A"; }\nif (x < 10) { std::cout << "B"; }', "AB", ["У второго if нет связи else с первым.", "Оба условия истинны."], "Независимые if могут выполнить обе ветви, и выводы соединятся без разделителя."),
                code("rectangle", "Груз проходит в шлюз?", 'Ввод: ширина груза w, высота h, ширина шлюза W, высота H (все 1…100). Груз нельзя поворачивать, равенство допустимо. Выведите Fit, если w≤W и h≤H, иначе Blocked.', 'int w = 0, h = 0, W = 0, H = 0;\nstd::cin >> w >> h >> W >> H;\nif (w <= W && h <= H) {\n    std::cout << "Fit";\n} else {\n    std::cout << "Blocked";\n}', [("4 3 4 3", "Fit"), ("5 2 4 8", "Blocked"), ("2 5 8 4", "Blocked")], ["Оба размера должны подходить одновременно.", "Не меняйте w и h местами: поворот запрещён условием."], "Смысловые ограничения важнее догадки о том, как было бы удобнее грузить.", difficulty=2),
                choice("conflict", "Проверка конфликта", 'Какой тест лучше всего проверит, что авария имеет приоритет над достаточным зарядом?', ["emergency=0, energy=10", "emergency=1, energy=100", "emergency=0, energy=100"], 1, ["Нужно одновременно выполнить аварийное и разрешающее обычное условие.", "В конфликте должен победить Stop."], "Тест с низким зарядом не отличит ошибочную проверку Go до аварии."),
                code("fare", "Умная билетная касса", 'Ввод: balance (0…10000), tickets (0…100). Цена одного билета 12. Если balance ≥ 12*tickets, выведите Bought и остаток через пробел; иначе Missing и недостающую сумму через пробел.', 'int balance = 0, tickets = 0;\nstd::cin >> balance >> tickets;\nint total = 12 * tickets;\nif (balance >= total) {\n    std::cout << "Bought " << balance - total;\n} else {\n    std::cout << "Missing " << total - balance;\n}', [("50 3", "Bought 14"), ("20 3", "Missing 16"), ("36 3", "Bought 0"), ("0 0", "Bought 0")], ["Сначала вычислите общую стоимость.", "В каждой ветви вычитайте меньшее из большего, но подписи различаются."], "Мини-проект расширяет кассу предыдущего раздела настоящей обработкой недостаточного бюджета.", difficulty=3)
            ], ["контрольная", "приоритет правил", "ветвления"])
    ])]
